1	import { createHash, createHmac, timingSafeEqual } from "node:crypto";
2	import { normalizeEmail } from "./index";
3	export { normalizeEmail };
4	
5	/** Minimal storage interface used by the Dio provider helpers. */
6	export interface DioStorage {
7		getItem: (key: string) => Promise<unknown>;
8		setItem: (key: string, value: any, opts?: any) => Promise<void>;
9	}
10	
11	export interface DioEnvConfig {
12		enabled: boolean;
13		creemApiKey: string;
14		creemWebhookSecret: string;
15		creemProductId: string;
16		creemBaseUrl: string;
17		dioCreditBudget: number;
18		bifrostApiKey: string;
19		bifrostBaseUrl: string;
20		bifrostModelAlias: string;
21		resendApiKey?: string;
22		recoveryFromEmail?: string;
23		recoveryDevCode: boolean;
24	}
25	
26	/**
27	 * Check whether the Dio provider is enabled without validating the rest of the
28	 * configuration. Routes use this to return early when the feature is off.
29	 */
30	export function isDioEnabled(): boolean {
31		if (process.env.DIO_ENABLED === "false") return false;
32		if (process.env.DIO_ENABLED === "true") return true;
33		return process.env.NODE_ENV === "development";
34	}
35	
36	export function getDioEnvConfig(): DioEnvConfig {
37		const creemApiKey = getRequiredEnv("CREEM_API_KEY");
38		const creemWebhookSecret = getRequiredEnv("CREEM_WEBHOOK_SECRET");
39		const creemProductId = getRequiredEnv("CREEM_PRODUCT_ID_DIO_CREDITS");
40		const dioCreditBudget = Number.parseInt(getRequiredEnv("DIO_CREDIT_BUDGET"), 10);
41		const bifrostApiKey = getRequiredEnv("BIFROST_API_KEY");
42		const bifrostBaseUrl = getDioGatewayBaseUrl();
43	
44		if (!Number.isFinite(dioCreditBudget) || dioCreditBudget <= 0) {
45			throw new Error("DIO_CREDIT_BUDGET must be a positive integer");
46		}
47	
48		return {
49			enabled: isDioEnabled(),
50			creemApiKey,
51			creemWebhookSecret,
52			creemProductId,
53			creemBaseUrl: resolveCreemBaseUrl(creemApiKey, process.env.CREEM_BASE_URL),
54			dioCreditBudget,
55			bifrostApiKey,
56			bifrostBaseUrl,
57			bifrostModelAlias: process.env.BIFROST_MODEL_ALIAS || "kimi-k2.6",
58			resendApiKey: process.env.RESEND_API_KEY?.trim(),
59			recoveryFromEmail: process.env.DIO_RECOVERY_FROM_EMAIL?.trim() || "support@keating.help",
60			recoveryDevCode: process.env.DIO_RECOVERY_DEV_CODE === "true" || process.env.NODE_ENV === "development",
61		};
62	}
63	
64	export function getDioGatewayBaseUrl(): string {
65		return getRequiredEnv("BIFROST_BASE_URL").replace(/\/+$/, "");
66	}
67	
68	function normalizeDioOpenAiProxyPath(path: string): string {
69		return path.split("?")[0].replace(/^\/+/, "").replace(/\/+$/, "");
70	}
71	
72	export function isAllowedDioOpenAiProxyRequest(method: string | undefined, path: string): boolean {
73		const normalizedMethod = (method || "GET").toUpperCase();
74		const normalizedPath = normalizeDioOpenAiProxyPath(path);
75		if (normalizedMethod === "POST") {
76			return normalizedPath === "v1/chat/completions";
77		}
78		if (normalizedMethod === "GET" || normalizedMethod === "HEAD") {
79			return normalizedPath === "v1/models";
80		}
81		return false;
82	}
83	
84	export function resolveCreemBaseUrl(apiKey: string, override?: string): string {
85		const configured = override?.trim();
86		if (configured) return configured;
87		return apiKey.startsWith("creem_test_")
88			? "https://test-api.creem.io/v1"
89			: "https://api.creem.io/v1";
90	}
91	
92	function getRequiredEnv(name: string): string {
93		const value = process.env[name]?.trim();
94		if (!value) {
95			throw new Error(`Missing required environment variable: ${name}`);
96		}
97		return value;
98	}
99	
100	export interface CreemCheckoutPayload {
101		email: string;
102	}
103	
104	export interface CreemCheckoutResponse {
105		checkoutUrl: string;
106		purchaseReference: string;
107	}
108	
109	export async function createCreemCheckout(
110		config: DioEnvConfig,
111		email: string,
112	): Promise<CreemCheckoutResponse> {
113		const normalized = normalizeEmail(email);
114		if (!isValidEmail(normalized)) {
115			throw new Error("Invalid email address");
116		}
117	
118		const purchaseReference = `dio_${cryptoUUID()}`;
119	
120		const response = await fetch(`${config.creemBaseUrl.replace(/\/+$/, "")}/checkouts`, {
121			method: "POST",
122			headers: {
123				"Content-Type": "application/json",
124				"x-api-key": config.creemApiKey,
125			},
126			body: JSON.stringify({
127				product_id: config.creemProductId,
128				success_url: `${process.env.KEATING_WEB_ORIGIN || ""}/dio/success?dio_ref=${encodeURIComponent(purchaseReference)}&dio_email=${encodeURIComponent(normalized)}`,
129				request_id: purchaseReference,
130				metadata: {
131					dio_purchase_reference: purchaseReference,
132					customer_email: normalized,
133				},
134			}),
135		});
136	
137		const body = await response.json().catch(() => ({}));
138		if (!response.ok) {
139			const message = body?.message || body?.error || `Creem checkout failed (${response.status})`;
140			throw new Error(message);
141		}
142	
143		const checkoutUrl = body?.checkout_url || body?.checkoutUrl;
144		if (typeof checkoutUrl !== "string") {
145			throw new Error("Creem checkout response missing checkout URL");
146		}
147	
148		return {
149			checkoutUrl,
150			purchaseReference,
151		};
152	}
153	
154	export interface CreemWebhookEvent {
155		id: string;
156		eventType: string;
157		created_at?: number;
158		object?: {
159			id?: string;
160			object?: string;
161			request_id?: string;
162			order?: { id?: string; product?: string; status?: string };
163			product?: { id?: string };
164			customer?: { id?: string; email?: string };
165			metadata?: Record<string, unknown>;
166		};
167	}
168	
169	export function parseCreemWebhookBody(body: unknown): CreemWebhookEvent {
170		if (!body || typeof body !== "object") {
171			throw new Error("Invalid webhook payload");
172		}
173		const payload = body as Record<string, unknown>;
174		if (typeof payload.id !== "string" || !payload.id) {
175			throw new Error("Invalid webhook event id");
176		}
177		if (typeof payload.eventType !== "string" || !payload.eventType) {
178			throw new Error("Invalid webhook event type");
179		}
180		if (!payload.object || typeof payload.object !== "object") {
181			throw new Error("Invalid webhook object");
182		}
183		return payload as unknown as CreemWebhookEvent;
184	}
185	
186	export function verifyCreemWebhookSignature(body: string, signature: string, secret: string): boolean {
187		if (!signature) return false;
188		const computed = createHmac("sha256", secret).update(body).digest("hex");
189		if (computed.length !== signature.length) return false;
190		try {
191			const computedBuf = Buffer.from(computed, "hex");
192			const signatureBuf = Buffer.from(signature, "hex");
193			return timingSafeEqual(computedBuf, signatureBuf);
194		} catch {
195			return false;
196		}
197	}
198	
199	export interface BifrostVirtualKeyRequest {
200		name: string;
201		description: string;
202		allowedModels: string[];
203		budget: { max: number };
204		metadata: Record<string, unknown>;
205		/** Unique key used to make Bifrost key creation idempotent for retries. */
206		idempotencyKey?: string;
207	}
208	
209	export interface BifrostVirtualKey {
210		id: string;
211		value: string;
212	}
213	
214	export async function createBifrostVirtualKey(
215		config: DioEnvConfig,
216		request: BifrostVirtualKeyRequest,
217	): Promise<BifrostVirtualKey> {
218		const url = `${config.bifrostBaseUrl.replace(/\/+$/, "")}/api/governance/virtual-keys`;
219		const headers: Record<string, string> = {
220			"Content-Type": "application/json",
221			Authorization: `Bearer ${config.bifrostApiKey}`,
222		};
223		if (request.idempotencyKey) {
224			headers["Idempotency-Key"] = request.idempotencyKey;
225		}
226		const response = await fetch(url, {
227			method: "POST",
228			headers,
229			body: JSON.stringify({
230				name: request.name,
231				description: request.description,
232				allowed_models: request.allowedModels,
233				budget: request.budget,
234				metadata: request.metadata,
235			}),
236		});
237	
238		const body = await response.json().catch(() => ({}));
239		if (!response.ok) {
240			const message = body?.message || body?.error || `Bifrost virtual key creation failed (${response.status})`;
241			throw new Error(message);
242		}
243	
244		const virtualKey = body?.virtual_key || body;
245		if (typeof virtualKey?.id !== "string" || typeof virtualKey?.value !== "string") {
246			throw new Error("Bifrost virtual key response missing id or value");
247		}
248	
249		return { id: virtualKey.id, value: virtualKey.value };
250	}
251	
252	export interface DioEntitlement {
253		email: string;
254		virtualKeyId: string;
255		virtualKeyValue: string;
256		purchaseReference?: string;
257		orderId?: string;
258		checkoutId?: string;
259		productId?: string;
260		customerId?: string;
261		createdAt: string;
262	}
263	
264	const ENTITLEMENT_KEY_PREFIX = "entitlement:";
265	const EVENT_KEY_PREFIX = "event:";
266	const RECOVERY_KEY_PREFIX = "recovery:";
267	const PROVISIONING_KEY_PREFIX = "provisioning:";
268	
269	/** How long a "processing" event lock remains valid before it is considered stale. */
270	export const EVENT_LOCK_TTL_MS = 5 * 60 * 1000;
271	
272	export interface DioEventRecord {
273		status: "processing" | "succeeded" | "failed";
274		createdAt: string;
275		lockId?: string;
276		error?: string;
277	}
278	
279	export interface RecoveryChallenge {
280		email: string;
281		otpHash: string;
282		expiresAt: string;
283		attempts: number;
284	}
285	
286	export interface DioProvisioningRecord {
287		purchaseReference: string;
288		email: string;
289		status: "provisioning" | "completed";
290		virtualKeyId?: string;
291		virtualKeyValue?: string;
292		createdAt: string;
293		updatedAt: string;
294	}
295	
296	export function entitlementStorageKey(email: string): string {
297		return `${ENTITLEMENT_KEY_PREFIX}${normalizeEmail(email)}`;
298	}
299	
300	function eventStorageKey(eventId: string): string {
301		return `${EVENT_KEY_PREFIX}${eventId}`;
302	}
303	
304	function recoveryStorageKey(email: string): string {
305		return `${RECOVERY_KEY_PREFIX}${normalizeEmail(email)}`;
306	}
307	
308	export function provisioningStorageKey(purchaseReference: string): string {
309		return `${PROVISIONING_KEY_PREFIX}${purchaseReference}`;
310	}
311	
312	function hashOtp(otp: string): string {
313		return createHash("sha256").update(otp).digest("hex");
314	}
315	
316	function generateOtp(): string {
317		return Array.from({ length: 6 }, () => Math.floor(Math.random() * 10)).join("");
318	}
319	
320	export async function createRecoveryChallenge(
321		storage: DioStorage,
322		email: string,
323	): Promise<string> {
324		const otp = generateOtp();
325		const challenge: RecoveryChallenge = {
326			email,
327			otpHash: hashOtp(otp),
328			expiresAt: new Date(Date.now() + 15 * 60 * 1000).toISOString(),
329			attempts: 0,
330		};
331		await storage.setItem(recoveryStorageKey(email), challenge);
332		return otp;
333	}
334	
335	export interface RecoveryEmailResult {
336		sent: boolean;
337		devCode?: string;
338		error?: string;
339	}
340	
341	/**
342	 * Send a recovery OTP email. When a real provider is configured, the code is
343	 * emailed. In development (or when DIO_RECOVERY_DEV_CODE=true) the code is
344	 * logged and returned so flows can be tested without a mail provider.
345	 */
346	export async function sendRecoveryEmail(
347		config: Pick<DioEnvConfig, "resendApiKey" | "recoveryFromEmail" | "recoveryDevCode">,
348		email: string,
349		otp: string,
350	): Promise<RecoveryEmailResult> {
351		if (config.resendApiKey && config.recoveryFromEmail) {
352			try {
353				const response = await fetch("https://api.resend.com/emails", {
354					method: "POST",
355					headers: {
356						"Content-Type": "application/json",
357						Authorization: `Bearer ${config.resendApiKey}`,
358					},
359					body: JSON.stringify({
360						from: config.recoveryFromEmail,
361						to: email,
362						subject: "Your Keating recovery code",
363						html: `<p>Your Keating recovery code is: <strong>${otp}</strong></p><p>This code expires in 15 minutes.</p>`,
364					}),
365				});
366				if (!response.ok) {
367					const body = await response.json().catch(() => ({}));
368					throw new Error(body?.message || `Resend returned ${response.status}`);
369				}
370				return { sent: true };
371			} catch (err) {
372				const message = err instanceof Error ? err.message : String(err);
373				console.error(`Failed to send recovery email to ${email}: ${message}`);
374				// In production (dev codes disabled), a provider failure must surface
375				// as an error so the client knows the code was not delivered.
376				if (!config.recoveryDevCode) {
377					return { sent: false, error: message };
378				}
379			}
380		}
381	
382		if (config.recoveryDevCode) {
383			console.log(`[Dio recovery dev code] ${email}: ${otp}`);
384			return { sent: false, devCode: otp };
385		}
386	
387		const message = "No recovery email provider configured";
388		console.warn(`${message}; OTP for ${email} was not sent.`);
389		return { sent: false, error: message };
390	}
391	
392	export async function verifyRecoveryChallenge(
393		storage: DioStorage,
394		email: string,
395		otp: string,
396	): Promise<boolean> {
397		const key = recoveryStorageKey(email);
398		const value = await storage.getItem(key);
399		if (!value || typeof value !== "object") {
400			return false;
401		}
402		const challenge = value as RecoveryChallenge;
403		if (challenge.attempts >= 5) {
404			return false;
405		}
406		if (new Date(challenge.expiresAt) < new Date()) {
407			await storage.setItem(key, { ...challenge, attempts: challenge.attempts + 1 });
408			return false;
409		}
410		const expectedHash = Buffer.from(challenge.otpHash, "hex");
411		const actualHash = Buffer.from(hashOtp(otp), "hex");
412		if (expectedHash.length !== actualHash.length) {
413			await storage.setItem(key, { ...challenge, attempts: challenge.attempts + 1 });
414			return false;
415		}
416		const ok = timingSafeEqual(expectedHash, actualHash);
417		if (!ok) {
418			await storage.setItem(key, { ...challenge, attempts: challenge.attempts + 1 });
419			return false;
420		}
421		await storage.setItem(key, { ...challenge, attempts: challenge.attempts + 1 });
422		return true;
423	}
424	
425	function isEventLockStale(record: DioEventRecord): boolean {
426		if (record.status !== "processing") return false;
427		const createdAt = record.createdAt ? new Date(record.createdAt).getTime() : 0;
428		return Number.isFinite(createdAt) && Date.now() - createdAt > EVENT_LOCK_TTL_MS;
429	}
430	
431	/** In-process serialization of lock attempts for the same event id. */
432	const eventLockPromises = new Map<string, Promise<boolean>>();
433	
434	async function acquireEventLockUncontended(storage: DioStorage, eventId: string): Promise<boolean> {
435		const key = eventStorageKey(eventId);
436		const existing = await storage.getItem(key);
437		if (existing && typeof existing === "object") {
438			const record = existing as DioEventRecord;
439			if (record.status === "succeeded") return false;
440			if (record.status === "processing" && !isEventLockStale(record)) return false;
441			// Stale "processing" lock or "failed" record: fall through and attempt
442			// to overwrite with a new lock.
443		}
444	
445		const lockId = cryptoUUID();
446		const record: DioEventRecord = {
447			status: "processing",
448			createdAt: new Date().toISOString(),
449			lockId,
450		};
451	
452		// Attempt an atomic write. Drivers that support {@code nx} will reject if the
453		// key already exists; drivers that do not support it will perform a plain set.
454		// The re-read below verifies that this process won the race.
455		try {
456			await storage.setItem(key, record, { nx: true });
457		} catch {
458			// nx may have been honored and failed, or the driver may have rejected the
459			// unknown option. Either way, verify ownership with the re-read.
460		}
461	
462		const reRead = await storage.getItem(key);
463		if (!reRead || typeof reRead !== "object") {
464			return false;
465		}
466		const reReadRecord = reRead as DioEventRecord;
467		return reReadRecord.status === "processing" && reReadRecord.lockId === lockId;
468	}
469	
470	/**
471	 * Acquire a per-event processing lock using a dedicated storage key.
472	 *
473	 * Returns false if the event has already succeeded or is currently being
474	 * processed by another worker. A previously "failed" event can be retried, and
475	 * "processing" locks older than {@link EVENT_LOCK_TTL_MS} are treated as stale
476	 * and may be re-acquired.
477	 *
478	 * The public entry point serializes callers for the same event within this
479	 * process, so multiple concurrent webhooks for one event cannot race here. The
480	 * underlying storage write attempts an atomic set-if-not-exists ({@code nx:
481	 * true}) when the driver supports it, then verifies ownership by reading the
482	 * stored lock id. For cross-process or multi-instance deployments, this relies
483	 * on the storage backend honoring {@code nx} (Redis, KV, etc.) or otherwise
484	 * providing linearizable writes; filesystem-backed storage without an atomic
485	 * CAS primitive cannot give a hard distributed-lock guarantee.
486	 */
487	export async function acquireEventLock(storage: DioStorage, eventId: string): Promise<boolean> {
488		const previous = eventLockPromises.get(eventId);
489		const current = (async () => {
490			await previous;
491			return acquireEventLockUncontended(storage, eventId);
492		})();
493		eventLockPromises.set(eventId, current);
494		try {
495			return await current;
496		} finally {
497			if (eventLockPromises.get(eventId) === current) {
498				eventLockPromises.delete(eventId);
499			}
500		}
501	}
502	
503	export async function completeEvent(
504		storage: DioStorage,
505		eventId: string,
506		succeeded: boolean,
507		error?: string,
508	): Promise<void> {
509		const key = eventStorageKey(eventId);
510		const record: DioEventRecord = {
511			status: succeeded ? "succeeded" : "failed",
512			createdAt: new Date().toISOString(),
513			error,
514		};
515		await storage.setItem(key, record);
516	}
517	
518	/** @deprecated Prefer {@link acquireEventLock} and {@link completeEvent}. */
519	export async function markEventProcessed(
520		storage: DioStorage,
521		eventId: string,
522	): Promise<boolean> {
523		const locked = await acquireEventLock(storage, eventId);
524		if (!locked) return false;
525		await completeEvent(storage, eventId, true);
526		return true;
527	}
528	
529	export async function loadDioEntitlement(
530		storage: DioStorage,
531		email: string,
532	): Promise<DioEntitlement | null> {
533		const value = await storage.getItem(entitlementStorageKey(email));
534		if (value && typeof value === "object") {
535			const entitlement = value as DioEntitlement;
536			if (
537				typeof entitlement.email === "string" &&
538				typeof entitlement.virtualKeyId === "string" &&
539				typeof entitlement.virtualKeyValue === "string"
540			) {
541				return entitlement;
542			}
543		}
544		return null;
545	}
546	
547	export async function saveDioEntitlement(
548		storage: DioStorage,
549		entitlement: DioEntitlement,
550	): Promise<void> {
551		await storage.setItem(entitlementStorageKey(entitlement.email), entitlement);
552	}
553	
554	export async function loadProvisioningRecord(
