		// Only mark the event as succeeded after the entitlement is persisted.
		// If persistence fails, the provision record lets retries complete it.
		await saveDioEntitlement(storage, entitlement);

		await saveProvisioningRecord(storage, {
			purchaseReference,
			email,
			status: "completed",
			virtualKeyId: virtualKey.id,
			virtualKeyValue: virtualKey.value,
			createdAt: now,
			updatedAt: new Date().toISOString(),
		});

		await completeEvent(storage, payload.id, true);

		return { received: true, handled: true, entitlement: { email, virtualKeyId: virtualKey.id } };
	} catch (err) {
		const message = err instanceof Error ? err.message : String(err);
		await completeEvent(storage, payload.id, false, message);
		throw createError({ statusCode: 500, statusMessage: message });
	}
});

import { createError, defineEventHandler, readBody } from "h3";
import { useStorage } from "nitro/storage";
import { createCreemCheckout, getDioEnvConfig, getPurchasableDioPack, isDioEnabled, normalizeEmail } from "../../../src/dio-provider/server";
import { DEFAULT_DIO_PACK_ID } from "../../../src/dio-provider/packs";

interface CheckoutBody {
	email?: string;
	packId?: string;
}

export default defineEventHandler(async (event) => {
	if (event.method !== "POST") {
		throw createError({ statusCode: 405, statusMessage: "Method not allowed" });
	}

	if (!isDioEnabled()) {
		throw createError({ statusCode: 404, statusMessage: "Not found" });
	}

	const body = await readBody<CheckoutBody>(event);
	const email = normalizeEmail(body?.email ?? "");
	if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
		throw createError({ statusCode: 400, statusMessage: "Valid email is required" });
	}

	const config = getDioEnvConfig();
	const packId = body?.packId?.trim() || DEFAULT_DIO_PACK_ID;
	if (!getPurchasableDioPack(config, packId)) {
		throw createError({ statusCode: 400, statusMessage: `Unknown or unavailable pack: ${packId}` });
	}
	const result = await createCreemCheckout(config, email, packId);

	const storage = useStorage("keating:dio");
	await storage.setItem(`pending:${normalizeEmail(email)}`, {
		purchaseReference: result.purchaseReference,
		email: normalizeEmail(email),
		packId,
		createdAt: new Date().toISOString(),
	});

	return result;
});

/**
 * Dio credit-pack catalog and advertised token pricing.
 *
 * Dependency-free so both the Vite client (pricing page, purchase dialog) and
 * the Nitro server (checkout, webhook) share one source of truth. Amounts are
 * USD; token rates are USD per million tokens and must match the model pricing
 * configured on the Bifrost gateway so credits draw down at the advertised
 * rate.
 */

export interface DioTokenRates {
	/** USD per 1M input tokens. */
	inputPerMTok: number;
	/** USD per 1M output tokens. */
	outputPerMTok: number;
}

export const DIO_TOKEN_RATES: DioTokenRates = {
	inputPerMTok: 1,
	outputPerMTok: 4,
};

export type DioPackId = "starter" | "plus" | "pro";

export interface DioPack {
	id: DioPackId;
	label: string;
	priceUsd: number;
	blurb: string;
	popular?: boolean;
}

export const DIO_PACKS: DioPack[] = [
	{
		id: "starter",
		label: "Starter",
		priceUsd: 10,
		blurb: "Try Keating's hosted model with room to learn a few topics deeply.",
	},
	{
		id: "plus",
		label: "Plus",
		priceUsd: 25,
		blurb: "Enough for regular study sessions, quizzes, and animations.",
		popular: true,
	},
	{
		id: "pro",
		label: "Pro",
		priceUsd: 50,
		blurb: "For daily learners and long-running projects.",
	},
];

export const DEFAULT_DIO_PACK_ID: DioPackId = "starter";

export function getDioPack(id: string): DioPack | undefined {
	return DIO_PACKS.find((pack) => pack.id === id);
}

export function isDioPackId(id: string): id is DioPackId {
	return DIO_PACKS.some((pack) => pack.id === id);
}

/** Millions of input tokens a dollar amount buys at the advertised rate. */
export function inputMTokForUsd(usd: number, rates: DioTokenRates = DIO_TOKEN_RATES): number {
	return usd / rates.inputPerMTok;
}

/** Millions of output tokens a dollar amount buys at the advertised rate. */
export function outputMTokForUsd(usd: number, rates: DioTokenRates = DIO_TOKEN_RATES): number {
	return usd / rates.outputPerMTok;
}

/** Human-readable token volume for a pack, e.g. "up to 10M in / 2.5M out". */
export function formatPackTokenVolume(pack: DioPack, rates: DioTokenRates = DIO_TOKEN_RATES): string {
	const input = formatMTok(inputMTokForUsd(pack.priceUsd, rates));
	const output = formatMTok(outputMTokForUsd(pack.priceUsd, rates));
	return `up to ${input} input / ${output} output tokens`;
}

function formatMTok(millions: number): string {
	const rounded = Number.isInteger(millions) ? millions.toString() : millions.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
	return `${rounded}M`;
}

import { describe, expect, it, mock } from "bun:test";
import {
	DIO_BASE_URL,
	DIO_BASE_PATH,
	DIO_DEFAULT_MODEL,
	DIO_DEFAULT_MODEL_ID,
	DIO_PROVIDER_ID,
	dioOpenAiBaseUrl,
	dioProviderDefinition,
	isDioProvider,
	normalizeEmail,
} from "../dio-provider";

describe("dio provider constants", () => {
	it("defines provider id, label, base url, and api", () => {
		expect(dioProviderDefinition.id).toBe("dio");
		expect(dioProviderDefinition.label).toBe("Dio");
		expect(dioProviderDefinition.baseUrl.endsWith(DIO_BASE_PATH)).toBe(true);
		expect(dioProviderDefinition.api).toBe("openai-completions");
	});

	it("exports stable module constants", () => {
		expect(DIO_PROVIDER_ID).toBe("dio");
		expect(DIO_BASE_PATH).toBe("/api/dio/openai/v1");
		expect(DIO_BASE_URL.endsWith(DIO_BASE_PATH)).toBe(true);
		expect(DIO_BASE_URL).not.toContain("bifrost");
		expect(DIO_DEFAULT_MODEL_ID).toBe("kimi-k2.6");
	});

	it("builds the Dio OpenAI base URL from the current app origin", () => {
		expect(dioOpenAiBaseUrl("https://keating.test/")).toBe("https://keating.test/api/dio/openai/v1");
	});

	it("defines the default model with expected shape", () => {
		expect(DIO_DEFAULT_MODEL.id).toBe("kimi-k2.6");
		expect(DIO_DEFAULT_MODEL.name).toBe("Kimi K2.6");
		expect(DIO_DEFAULT_MODEL.provider).toBe("dio");
		expect(DIO_DEFAULT_MODEL.api).toBe("openai-completions");
		expect(DIO_DEFAULT_MODEL.baseUrl).toBe(DIO_BASE_URL);
		expect(DIO_DEFAULT_MODEL.reasoning).toBe(true);
		expect(DIO_DEFAULT_MODEL.input).toEqual(["text"]);
		expect(DIO_DEFAULT_MODEL.contextWindow).toBeGreaterThanOrEqual(256_000);
		expect(DIO_DEFAULT_MODEL.maxTokens).toBeGreaterThan(0);
		expect(DIO_DEFAULT_MODEL.cost).toEqual({
			input: 0,
			output: 0,
			cacheRead: 0,
			cacheWrite: 0,
		});
	});

	it("normalizes emails to lowercase and trimmed", () => {
		expect(normalizeEmail("  ExamPle@Dio.Computer  ")).toBe("example@dio.computer");
		expect(normalizeEmail("user@example.com")).toBe("user@example.com");
	});

	it("identifies dio provider by id", () => {
		expect(isDioProvider("dio")).toBe(true);
		expect(isDioProvider("openai")).toBe(false);
		expect(isDioProvider("google")).toBe(false);
	});
});

describe("dio proxy behavior", () => {
	it("routes dio requests through the dedicated same-origin gateway proxy", async () => {
		const { shouldProxyModel } = await import("../lib/provider-proxy");
		expect(shouldProxyModel(DIO_DEFAULT_MODEL)).toBe(false);
		expect(DIO_DEFAULT_MODEL.baseUrl.endsWith("/api/dio/openai/v1")).toBe(true);
		expect(DIO_DEFAULT_MODEL.baseUrl).not.toContain("bifrost");
	});
});

describe("dio selectable model ordering", () => {
	mock.module("@earendil-works/pi-web-ui", () => ({
		getAppStorage: () => ({
			customProviders: { getAll: async () => [] },
			providerKeys: { get: async () => undefined },
		}),
	}));

	it("places the dio model first in selectable models", async () => {
		const { getSelectableModels } = await import("../lib/provider-models");
		const models = await getSelectableModels();
		expect(models.length).toBeGreaterThan(0);
		expect(models[0].provider).toBe("dio");
		expect(models[0].id).toBe("kimi-k2.6");
	});

	it("respects provider filter for dio", async () => {
		const { getSelectableModels } = await import("../lib/provider-models");
		const models = await getSelectableModels((provider) => provider === "dio");
		expect(models.every((model) => model.provider === "dio")).toBe(true);
		expect(models[0].id).toBe("kimi-k2.6");
	});
});

describe("dio default stream model", () => {
	it("uses dio default model as the chat default", async () => {
		const { DEFAULT_MODEL } = await import("../hooks/keating-stream");
		expect(DEFAULT_MODEL.provider).toBe("dio");
		expect(DEFAULT_MODEL.id).toBe("kimi-k2.6");
	});
});

