1	import { useEffect, useState } from "react";
2	import { getAppStorage } from "@earendil-works/pi-web-ui";
3	import { KeyRound, X } from "lucide-react";
4	import {
5		DIO_PROVIDER_ID,
6		claimDioAccess,
7		isDioFeatureEnabled,
8		recoverDioAccess,
9		startDioCheckout,
10		normalizeEmail,
11		rememberDioIdentity,
12	} from "../dio-provider";
13	
14	type DioPromptRequest = {
15		id: string;
16		resolve: (success: boolean) => void;
17	};
18	
19	let activeDioPrompt: DioPromptRequest | null = null;
20	
21	export function getActiveDioPrompt(): DioPromptRequest | null {
22		return activeDioPrompt;
23	}
24	
25	function emitDioPromptChange() {
26		window.dispatchEvent(new CustomEvent("keating:dio-prompt-changed"));
27	}
28	
29	export async function promptDioAccess(): Promise<boolean> {
30		if (typeof window === "undefined") return false;
31		if (!isDioFeatureEnabled()) return false;
32	
33		const existing = await getAppStorage().providerKeys.get(DIO_PROVIDER_ID);
34		if (existing) return true;
35	
36		if (activeDioPrompt) {
37			activeDioPrompt.resolve(false);
38		}
39	
40		return new Promise((resolve) => {
41			activeDioPrompt = {
42				id: crypto.randomUUID(),
43				resolve,
44			};
45			emitDioPromptChange();
46		});
47	}
48	
49	export function closeDioPrompt(success: boolean) {
50		if (!activeDioPrompt) return;
51		const request = activeDioPrompt;
52		activeDioPrompt = null;
53		request.resolve(success);
54		emitDioPromptChange();
55	}
56	
57	export function DioAccessPromptDialog() {
58		const [request, setRequest] = useState(activeDioPrompt);
59		const [email, setEmail] = useState("");
60		const [mode, setMode] = useState<"purchase" | "recover" | "manual">("purchase");
61		const [apiKey, setApiKey] = useState("");
62		const [purchaseReference, setPurchaseReference] = useState("");
63		const [otp, setOtp] = useState("");
64		const [requiresOtp, setRequiresOtp] = useState(false);
65		const [devCode, setDevCode] = useState("");
66		const [loading, setLoading] = useState(false);
67		const [error, setError] = useState("");
68	
69		useEffect(() => {
70			const sync = () => {
71				setRequest(activeDioPrompt);
72				setEmail("");
73				setMode("purchase");
74				setApiKey("");
75				setPurchaseReference("");
76				setOtp("");
77				setRequiresOtp(false);
78				setDevCode("");
79				setError("");
80				setLoading(false);
81			};
82			window.addEventListener("keating:dio-prompt-changed", sync);
83			return () => window.removeEventListener("keating:dio-prompt-changed", sync);
84		}, []);
85	
86		if (!request) return null;
87	
88		const saveManualKey = async () => {
89			const trimmed = apiKey.trim();
90			if (!trimmed) {
91				setError("Enter an API key first.");
92				return;
93			}
94			setLoading(true);
95			setError("");
96			try {
97				await getAppStorage().providerKeys.set(DIO_PROVIDER_ID, trimmed);
98				closeDioPrompt(true);
99			} catch (err) {
100				setError(err instanceof Error ? err.message : String(err));
101			} finally {
102				setLoading(false);
103			}
104		};
105	
106		const doCheckout = async () => {
107			const normalized = normalizeEmail(email);
108			if (!isValidEmail(normalized)) {
109				setError("Enter a valid email address.");
110				return;
111			}
112			setLoading(true);
113			setError("");
114			try {
115				const result = await startDioCheckout(normalized);
116				setPurchaseReference(result.purchaseReference);
117				window.open(result.checkoutUrl, "_blank", "noopener,noreferrer");
118			} catch (err) {
119				setError(err instanceof Error ? err.message : String(err));
120			} finally {
121				setLoading(false);
122			}
123		};
124	
125		const doClaim = async () => {
126			const normalized = normalizeEmail(email);
127			if (!isValidEmail(normalized)) {
128				setError("Enter a valid email address.");
129				return;
130			}
131			setLoading(true);
132			setError("");
133			try {
134				const result = await claimDioAccess(normalized, purchaseReference || undefined);
135				if (result.success && result.apiKey) {
136					await getAppStorage().providerKeys.set(DIO_PROVIDER_ID, result.apiKey);
137					await rememberDioIdentity(normalized);
138					closeDioPrompt(true);
139				} else if (result.pending) {
140					setError("Purchase is still pending. Complete payment and try again.");
141				} else {
142					setError("Could not find a completed purchase for this email.");
143				}
144			} catch (err) {
145				setError(err instanceof Error ? err.message : String(err));
146			} finally {
147				setLoading(false);
148			}
149		};
150	
151		const doRecover = async () => {
152			const normalized = normalizeEmail(email);
153			if (!isValidEmail(normalized)) {
154				setError("Enter a valid email address.");
155				return;
156			}
157			setLoading(true);
158			setError("");
159			try {
160				const result = await recoverDioAccess(normalized, otp || undefined);
161				if (result.success && result.apiKey) {
162					await getAppStorage().providerKeys.set(DIO_PROVIDER_ID, result.apiKey);
163					await rememberDioIdentity(normalized);
164					closeDioPrompt(true);
165				} else if (result.requiresOtp) {
166					setRequiresOtp(true);
167					setDevCode(result.devCode || "");
168					setError(otp ? "Invalid or expired code." : "Enter the verification code sent to your email.");
169				} else {
170					setError("No active access found for this email.");
171				}
172			} catch (err) {
173				setError(err instanceof Error ? err.message : String(err));
174			} finally {
175				setLoading(false);
176			}
177		};
178	
