33	/**
34	 * Check whether the Dio provider is enabled without validating the rest of the
35	 * configuration. Routes use this to return early when the feature is off.
36	 */
37	export function isDioEnabled(): boolean {
38		if (process.env.DIO_ENABLED === "false") return false;
39		if (process.env.DIO_ENABLED === "true") return true;
40		return process.env.NODE_ENV === "development";
41	}
42	
43	export function getDioEnvConfig(): DioEnvConfig {
44		const creemApiKey = getRequiredEnv("CREEM_API_KEY");
45		const creemWebhookSecret = getRequiredEnv("CREEM_WEBHOOK_SECRET");
46		const packs = getDioPacksFromEnv(process.env);
47		const bifrostApiKey = getRequiredEnv("BIFROST_API_KEY");
48		const bifrostBaseUrl = getDioGatewayBaseUrl();
49	
50		return {
51			enabled: isDioEnabled(),
52			creemApiKey,
53			creemWebhookSecret,
54			creemBaseUrl: resolveCreemBaseUrl(creemApiKey, process.env.CREEM_BASE_URL),
55			packs,
56			bifrostApiKey,
57			bifrostBaseUrl,
58			bifrostModelAlias: process.env.BIFROST_MODEL_ALIAS || "kimi-k2.6",
59			resendApiKey: process.env.RESEND_API_KEY?.trim(),
60			recoveryFromEmail: process.env.DIO_RECOVERY_FROM_EMAIL?.trim() || "support@keating.help",
61			recoveryDevCode: process.env.DIO_RECOVERY_DEV_CODE === "true" || process.env.NODE_ENV === "development",
62		};
