});

describe("updateBifrostVirtualKeyBudget", () => {
	it("PUTs the summed budget to the governance endpoint", async () => {
		let captured: { url: string; method: string; body: any } | null = null;
		globalThis.fetch = (async (url: any, init: any) => {
